from pathlib import Path
import subprocess,json,stat,os,hashlib,datetime
r=Path('/var/tmp/hfs-run-20261030-n17');out={'observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat()}
for name,argv in [('processes',['ps','-axo','pid,ppid,lstart,command']),('mounts',['mount','-p'])]:
 p=subprocess.run(argv,capture_output=True,text=True,check=True,timeout=8)
 out[name]=[line for line in p.stdout.splitlines() if '20261030-n17' in line]
files={}
for suffix in ['json','stderr','stdout','exit.json','process.json','xml']:
 p=r/'evidence'/('unprivileged-hfs-buffered.'+suffix)
 if not p.exists():files[p.name]={'absent':True};continue
 st=p.lstat();assert stat.S_ISREG(st.st_mode) and st.st_uid==0 and st.st_nlink==1 and st.st_size<=262144
 raw=p.read_bytes();files[p.name]={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'text':raw.decode()}
out['files']=files
print(json.dumps(out))
